    private static final DateTimeFormatter TIME_FORMAT = DateTimeFormatter.ofPattern("h:mm a");

    private final SkyCyclePlugin plugin;
    private final SkyCycleConfig config;
    private final PanelComponent panelComponent = new PanelComponent();

    @Inject
    public SkyCycleOverlay(SkyCyclePlugin plugin, SkyCycleConfig config)
    {
        super(plugin);
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_SCENE);
        setPriority(OverlayPriority.LOW);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showOverlay()) return null;

        CycleEngine engine = plugin.getCycleEngine();
        if (engine == null) return null;

        panelComponent.getChildren().clear();

        CyclePhase phase = engine.getCurrentPhase();
        boolean isUnderground = plugin.isCurrentlyUnderground();
        String phaseText = isUnderground ? "Underground" : phase.getDisplayName();
        Color phaseColor = isUnderground ? new Color(120, 120, 120) : phase.getOverlayColor();
        int remainingSeconds = engine.getPhaseRemainingSeconds();
        String timeStr = formatTime(remainingSeconds);

        if (config.condensedOverlay())
        {
            String condensedText;
            if (config.syncToLocalClock())
            {
                condensedText = phaseText + " (" + LocalTime.now().format(TIME_FORMAT) + ")";
            }
            else
            {
                condensedText = phaseText + ": " + (isUnderground ? "--:--" : timeStr);
            }

            panelComponent.getChildren().add(TitleComponent.builder()
                .text(condensedText)
                .color(phaseColor)
                .build());
            panelComponent.setPreferredSize(new Dimension(130, 0));
        }
        else
        {
            panelComponent.getChildren().add(TitleComponent.builder()
                .text("Divine: Skies")
                .color(phaseColor)
                .build());

            panelComponent.getChildren().add(LineComponent.builder()
                .left("Phase:")
                .right(phaseText)
                .rightColor(phaseColor)
                .build());

            if (!isUnderground)
            {
                if (config.syncToLocalClock())
                {
                    panelComponent.getChildren().add(LineComponent.builder()
                        .left("Time:")
                        .right(LocalTime.now().format(TIME_FORMAT))
                        .build());

                    panelComponent.getChildren().add(LineComponent.builder()
                        .left("Next in:")
                        .right(timeStr)
                        .build());
                }
                else
                {
                    panelComponent.getChildren().add(LineComponent.builder()
                        .left("Remaining:")
                        .right(timeStr)
                        .build());

                    double progress = engine.getPhaseProgress();
                    String bar = buildProgressBar(progress, 10);
                    panelComponent.getChildren().add(LineComponent.builder()
                        .left("")
                        .right(bar)
                        .rightColor(phaseColor)
                        .build());
                }
            }

            // Developer Mode: show region/instance/plane info for community bug reporting
            if (config.devMode())
            {
                UndergroundDetector detector = plugin.getUndergroundDetector();
                int[] regions = plugin.getClient().getMapRegions();

                int resolved = detector.getResolvedRegion();
                panelComponent.getChildren().add(LineComponent.builder()
                    .left("Region (resolved):")
                    .right(resolved >= 0 ? String.valueOf(resolved) : "—")
                    .rightColor(new Color(200, 200, 120))
                    .build());

                if (regions != null)
                {
                    panelComponent.getChildren().add(LineComponent.builder()
                        .left("Loaded:")
                        .right(java.util.Arrays.toString(regions))
                        .rightColor(new Color(180, 180, 180))
                        .build());
                }

                panelComponent.getChildren().add(LineComponent.builder()
                    .left("Instance:")
                    .right(String.valueOf(plugin.getClient().isInInstancedRegion()))
                    .rightColor(new Color(180, 180, 180))
                    .build());

                panelComponent.getChildren().add(LineComponent.builder()
                    .left("Plane:")
                    .right(String.valueOf(plugin.getClient().getPlane()))
                    .rightColor(new Color(180, 180, 180))
                    .build());

                AreaType override = detector.getCurrentOverride();
                panelComponent.getChildren().add(LineComponent.builder()
                    .left("Override:")
                    .right(override == null ? "none (auto)" : override.getDisplayName())
                    .rightColor(override == null ? new Color(140, 140, 140) : new Color(120, 220, 140))
                    .build());

                if (detector.getOverrideCount() > 0)
                {
                    panelComponent.getChildren().add(LineComponent.builder()
                        .left("Saved overrides:")
                        .right(String.valueOf(detector.getOverrideCount()))
                        .rightColor(new Color(180, 180, 180))
                        .build());
                }
            }

            panelComponent.setPreferredSize(new Dimension(
                config.devMode() ? 220 : 140, 0));
        }

        return panelComponent.render(graphics);
    }

    private static String formatTime(int totalSeconds)
    {
        if (totalSeconds >= 3600)
        {
            int hours = totalSeconds / 3600;
            int minutes = (totalSeconds % 3600) / 60;
            return String.format("%d:%02d:%02d", hours, minutes, totalSeconds % 60);
        }
        int minutes = totalSeconds / 60;
        int seconds = totalSeconds % 60;
        return String.format("%d:%02d", minutes, seconds);
    }

    private static String buildProgressBar(double progress, int length)
    {
        int filled = (int) Math.round(progress * length);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < length; i++)
        {
            sb.append(i < filled ? '\u2588' : '\u2591');
        }
        return sb.toString();
    }
}

